from rest_framework.views import APIView
from rest_framework.response import Response
from rest_framework.permissions import IsAuthenticated
from rest_framework.exceptions import PermissionDenied, NotFound
from rest_framework import status
from invitations.models import Invitation

class ResendInvitationView(APIView):
    permission_classes = [IsAuthenticated]

    def post(self, request, invitation_id: int):
        try:
            invitation = Invitation.objects.get(id=invitation_id)
        except Invitation.DoesNotExist:
            raise NotFound("Invitation not found")

        # Enforce that the caller belongs to the inviting organization and has administrative permissions
        if invitation.inviter.organization != request.user.organization or not request.user.has_perm('invitations.change_invitation'):
            raise PermissionDenied("You are not authorized to modify or resend this invitation")

        invitation.send_invitation(request)
        return Response({'status': 'resent', 'email': invitation.email})
